      "name": "sq_lt_sq₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : LinearOrder M₀] [PosMulStrictMono M₀] {a b : M₀} [MulPosMono M₀],\n  0 ≤ a → 0 ≤ b → (a ^ 2 < b ^ 2 ↔ a < b)"
    },
    {
      "name": "nonneg_le_nonneg_of_sq_le_sq",
      "module_name": "Mathlib.Algebra.Order.Ring.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [inst_1 : LinearOrder R] [PosMulStrictMono R] [MulPosMono R] {a b : R},\n  0 ≤ b → a * a ≤ b * b → a ≤ b"
    },
    {
      "name": "mul_self_le_mul_self_iff",
      "module_name": "Mathlib.Algebra.Order.Ring.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [inst_1 : LinearOrder R] [PosMulStrictMono R] [MulPosMono R] {a b : R},\n  0 ≤ a → 0 ≤ b → (a ≤ b ↔ a * a ≤ b * b)"
    },
    {
      "name": "mul_self_le_mul_self",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : MulZeroClass α] {a b : α} [inst_1 : Preorder α] [PosMulMono α] [MulPosMono α],\n  0 ≤ a → a ≤ b → a * a ≤ b * b"
    },
    {
      "name": "mul_self_lt_mul_self_iff",
      "module_name": "Mathlib.Algebra.Order.Ring.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [inst_1 : LinearOrder R] [PosMulStrictMono R] [MulPosMono R] {a b : R},\n  0 ≤ a → 0 ≤ b → (a < b ↔ a * a < b * b)"
    }
  ]
}
